-- PORTFOLIO PROJECT:


-- IMPORTANT:
-- This file contains database setup and data-loading statements.
-- TRUNCATE TABLE statements delete existing table data.
-- Do not run the entire file against a database containing data you need.
-- Run the analysis queries separately after the data has been loaded.

CREATE database ecommerce_analytics; 
USE ecommerce_analytics;

CREATE TABLE customers ( customer_id INT PRIMARY KEY,name VARCHAR(100),region VARCHAR(50), sign_up DATE); 

CREATE TABLE categories ( category_id int primary key ,category_name VARCHAR(100));

CREATE TABLE products (product_id INT primary key ,product_name VARCHAR(100),category_id int, price decimal(10,2),
foreign key(category_id) references categories(category_id)); 

 CREATE TABLE orders (order_id int primary key, customer_id int,order_date date, status varchar(50),
 foreign key(customer_id) references customers(customer_id)); 
 
 
 CREATE TABLE order_items ( order_item_id int primary key,order_ID int,product_ID INT, quantity int,unit_price decimal(10,2),
 foreign key (order_id) references orders(order_id),
 foreign key (product_id) references products(product_id));
 
 CREATE TABLE payments ( payment_id int primary key,order_id int, payment_date date,amount decimal (10,2), payment_method varchar(100)
 ,foreign key (order_id) references orders(order_id));

SHOW TABLES;
DESCRIBE customers;
DESCRIBE categories;
DESCRIBE products;
DESCRIBE orders;
DESCRIBE order_items;
DESCRIBE payments;

-- E-Commerce Analytics Portfolio Project Data
