-- =====================================================
-- E-COMMERCE ANALYTICS PROJECT
-- SECTION 1: CUSTOMER ANALYSIS
-- =====================================================

-- Row counts after import:
-- categories: 10
-- products: 50
-- customers: 1000
-- orders: 5000
-- order_items: 10331
-- payments: 4516

select * from customers;
select * from categories;
select * from order_items;
select * from orders;
select * from payments;
select * from products;

SELECT 'customers' AS table_name, COUNT(*) AS row_count
FROM customers

UNION ALL

SELECT 'products', COUNT(*)
FROM products

UNION ALL

SELECT 'categories', COUNT(*)
FROM categories

UNION ALL

SELECT 'orders', COUNT(*)
FROM orders

UNION ALL

SELECT 'order_items', COUNT(*)
FROM order_items

UNION ALL

SELECT 'payments', COUNT(*)
FROM payments;

-- Data Exploration & Quality:

-- 1- How many customers in each region?

select 
region,
count(customer_id) as customer_count 
from customers 
group by region 
order by customer_count desc;

-- 2- How many orders are there for each status?

select 
status, 
	count(order_id) as order_count
from orders
group by status;

-- 3- What is the earliest and latest order date?

select min(order_date) as earliest_order,max(order_date) as latest_order from orders;

-- 4- . What are the different payment methods and how many payments use each one?

select payment_method, count(payment_id) as payment_count from payments
 group by payment_method order by payment_count desc ;

-- 5- Total payment amount.

select sum(amount) as total_payments from payments;

-- 6- Average payment amount.

select avg(amount) as Average_payment_amount from payments;

-- 7- Average number of items per order.

select 
sum(quantity)/count(distinct order_id) as avg_items_per_order 
from order_items;

-- 8- Which customers have placed the most orders?

select 
c.customer_id,
c.name,
count(o.order_id) order_count
from customers c left join orders o 
on c.customer_id=o.customer_id
group by c.customer_id,c.name
order by order_count desc;

-- 9- Which 10 customers have generated the highest total payment amount?

select 
c.customer_id,
c.name,
sum(p.amount) as total_amount 
from customers c 
left join 
orders o 
on 
c.customer_id=o.customer_id 
join payments p 
on 
p.order_id = o.order_id
group by 
c.customer_id,c.name
order by total_amount desc 
limit 10;

-- 10- What percentage of the company's total payments came from each of the top 10 customers?

WITH customer_spending AS (
    SELECT 
        c.customer_id,
        c.name,
        SUM(p.amount) AS total_spent
    FROM customers c
    JOIN orders o 
        ON c.customer_id = o.customer_id
    JOIN payments p 
        ON o.order_id = p.order_id
    GROUP BY c.customer_id, c.name
)

SELECT
    customer_id,
    name,
    total_spent,
    ROUND(
        total_spent / (SELECT SUM(amount) FROM payments) * 100,
        2
    ) AS percentage_of_total
FROM customer_spending
ORDER BY total_spent DESC
LIMIT 10;

-- 10- How much revenue did the business generate each month?

select  
date_format(payment_date,'%Y-%m') as month,
 sum(amount) as total_revenue 
 from payments 
 group by month 
 order by month;
 
 -- 11- Calculate monthly revenue AND the previous month's revenue in the same result.
 
with monthly_revenue as(select  
date_format(payment_date,'%Y-%m') as month,
 sum(amount) as total_revenue 
 from payments 
 group by month)
 select month,total_revenue,lag(total_revenue) over (order by month) as previous_month_revenue from monthly_revenue;
 
 -- 12- What was the month-over-month percentage change in revenue?

with monthly_revenue as
(select  
date_format(payment_date,'%Y-%m') as month,
 sum(amount) as total_revenue 
 from payments 
 group by month),
 lag_value as 
 (select month,
 total_revenue,
 lag(total_revenue) over (order by month) as previous_month_revenue 
 from monthly_revenue)
 select 
 month,
 total_revenue,
 previous_month_revenue,
 round((total_revenue - previous_month_revenue)/nullif(previous_month_revenue,0) * 100,2) 
 as percentage_change 
 from 
 lag_value;

-- 13- For each customer, find their first order date and most recent order date.

select 
c.customer_id,
c.name,
min(o.order_date) as first_order_date,
max(o.order_date) as latest_order_date 
from customers c left join orders o on c.customer_id = o.customer_id
group by 
c.customer_id,c.name;

-- 14- Calculate the total amount each customer has spent, along with their first and latest order dates.

select 
c.customer_id,
c.name,
min(o.order_date) as first_order_date,
max(o.order_date) as latest_order_date, 
sum(p.amount) as amount_spent 
from customers c 
left join 
orders o 
on
c.customer_id =o.customer_id 
left join 
payments p 
on 
p.order_id=o.order_id
group by 
c.name,customer_id;


--  Customer Segmentation:

with total_spent as 
(select c.customer_id,
c.name,
coalesce(sum(p.amount),0) as total_spent 
from customers c left join orders o 
on 
c.customer_id = o.customer_id 
left join 
payments p 
on 
p.order_id=o.order_id 
group by c.customer_id,c.name)
select customer_id,name,total_spent, case
when total_spent <=500 then "low value"
when total_spent <=1500 then "medium value"
when total_spent >1500 then "High value" end 
as customer_category 
from total_spent order by total_spent desc;


-- =====================================================
-- SECTION 3: CUSTOMER SEGMENTATION (RFM)
-- =====================================================

-- 15- RFM Style customer Analysis 
-- RECENCY (DAYS SINCE LAST ORDER)
-- FREQUENCY (COUNT)
-- MONETARY (TOTAL SPENT)

-- For each customer, calculate:
-- Last order date → MAX(order_date), Order count → COUNT(order_id), Total spent → SUM(payment amount)

with last_order as(select 
c.customer_id,
c.name, 
max(o.order_date) as last_order_date, 
count(distinct o.order_id) as order_count, 
sum(p.amount) as total_spent
from 
customers c 
left join orders o 
on 
c.customer_id = o.customer_id 
left join 
payments p 
on 
p.order_id=o.order_id 
group by c.customer_id,c.name)
select customer_id,
name,
last_order_date,
order_count,
total_spent,
datediff(curdate(),last_order_date) 
as days_from_last_order 
from last_order;

-- RFM segmentation

-- recency_segment
-- 0–30 days       → Recent
-- 31–90 days      → At Risk
-- 91+ days        → Inactive

-- frequency_segment
-- 1–2 orders      → Low Frequency
-- 3–5 orders      → Medium Frequency
-- 6+ orders       → High Frequency

-- CUSTOMER_ID, NAME,LAST_ORDER_DATE,ORDER_COUNT,TOTAL_SPENT,DAYS_FROM_LAST_ORDER.

with last_order as 
(select 
c.customer_id,
c.name,
max(o.order_date) as last_order_date,
count(distinct o.order_id) as order_count,
sum(p.amount) as total_spent
from 
customers c left join orders o 
on
c.customer_id=o.customer_id 
left join payments p 
on
p.order_id = o.order_id
group by c.customer_id,c.name),
recency as (select 
customer_id,
name,
last_order_date,
order_count,
total_spent,
datediff(curdate(),last_order_date)as Total_days_from_last_order 
from last_order)
select customer_id,
name,
last_order_date,
order_count,
total_spent,
Total_days_from_last_order,
case
when Total_days_from_last_order <= 30 then 'recent'
when Total_days_from_last_order <=90 then 'At Risk'
when Total_days_from_last_order >90 then 'Inactive' end as recency_segment,
case
when order_count <=2 then 'low frequency'
 when order_count <=5 then 'medium frequency'
 when order_count >=6 then 'high frequency' end as frequency_segment 
 from recency;
 

-- Monetary segments
-- Total Spent	Segment
-- ≤ $500	Low Monetary
-- $500–$1,500	Medium Monetary
-- > $1,500	High Monetary

with last_order as 
(select 
c.customer_id,
c.name,
max(o.order_date) as last_order_date,
count(distinct o.order_id) as order_count,
sum(p.amount) as total_spent
from 
customers c left join orders o 
on
c.customer_id=o.customer_id 
left join payments p 
on
p.order_id = o.order_id
group by c.customer_id,c.name),
recency as (select 
customer_id,
name,
last_order_date,
order_count,
total_spent,
datediff(curdate(),last_order_date)as Total_days_from_last_order 
from last_order)
select customer_id,
name,
last_order_date,
order_count,
total_spent,
Total_days_from_last_order,
case
when Total_days_from_last_order <= 30 then 'recent'
when Total_days_from_last_order <=90 then 'At Risk'
else 'Inactive' end as recency_segment,
case
when order_count <=2 then 'low frequency'
 when order_count <=5 then 'medium frequency'
else 'high frequency' end as frequency_segment,
case
when total_spent<=500 then 'low monetary'
when total_spent<=1500 then 'medium monetary'
else 'high monetary' end as monetary_segment 
 from recency;


with last_order as 
(select 
c.customer_id,
c.name,
max(o.order_date) as last_order_date,
count(distinct o.order_id) as order_count,
sum(p.amount) as total_spent
from 
customers c left join orders o 
on
c.customer_id=o.customer_id 
left join payments p 
on
p.order_id = o.order_id
group by c.customer_id,c.name),
recency as (select 
customer_id,
name,
last_order_date,
order_count,
total_spent,
datediff(curdate(),last_order_date)as Total_days_from_last_order 
from last_order),
scores as (select customer_id,
name,
last_order_date,
order_count,
total_spent,
Total_days_from_last_order,
case
when Total_days_from_last_order <= 30 then 5
when Total_days_from_last_order <=60 then 4
when Total_days_from_last_order <=90 then 3
when Total_days_from_last_order <=180 then 2
else 1 end as recency_score,
case
when order_count <=2 then 1
when order_count <=4 then 2
when order_count <=6 then 3
when order_count <=8 then 4
else 5 end as frequency_score,
case
when total_spent<=500 then 1
when total_spent<=1000 then 2
when total_spent<=1500 then 3
when total_spent<=2000 then 4
else 5 end as monetary_score 
 from recency),
 RFM as (SELECT
 customer_id,
name,
last_order_date,
order_count,
total_spent,
Total_days_from_last_order,
recency_score,
frequency_score,
monetary_score,
recency_score +frequency_score+monetary_score as RFM_SCORE
from SCORES)
select customer_id,
name,
last_order_date,
order_count,
total_spent,
Total_days_from_last_order,
recency_score,
frequency_score,
monetary_score,
RFM_score,
concat
(recency_score,frequency_score,monetary_score) 
as RFM_code from 
RFM order by RFM_score desc;





